import java.util.Scanner;

public class Main {
    public static int computeGCD(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int maxDenom = sc.nextInt();

        int g = computeGCD(a, b);
        a /= g;
        b /= g;

        if (maxDenom >= b) {
            System.out.println(a + "/" + b);
        } else {
            double ratio = (double) a / b;
            double bestDiff = ratio;
            int bestNum = 0;
            int bestDen = 1;

            for (int i = 1; i <= maxDenom; ++i) {
                double val = i * ratio;
                double floorVal = Math.floor(val);
                double diffLower = Math.abs(floorVal / i - ratio);
                double diffUpper = Math.abs((floorVal + 1) / i - ratio);

                if (bestDiff > diffLower || bestDiff > diffUpper) {
                    if (diffLower > diffUpper) {
                        bestNum = (int) (floorVal + 1);
                    } else {
                        bestNum = (int) floorVal;
                    }
                    bestDen = i;
                    bestDiff = Math.min(diffLower, diffUpper);
                }
            }
            System.out.println(bestNum + "/" + bestDen);
        }
        sc.close();
    }
}
